const ARCHIVE_KEY='flpr_verified_tournaments_v1';
function loadImportedTournaments(){try{const raw=localStorage.getItem(ARCHIVE_KEY);const parsed=raw?JSON.parse(raw):[];return Array.isArray(parsed)?parsed:[];}catch(e){console.warn('Archive load failed',e);return [];}}
function tournamentSequence(t){const candidates=[t.id,t.sourceTournamentId,t.name];for(const value of candidates){const m=String(value||'').match(/(?:^|\b)T\s*0*(\d+)(?:\b|$)/i);if(m)return Number(m[1]);}return Number.MAX_SAFE_INTEGER;}
function tournamentDisplayName(t,index=null){
  if(DATA?.currentCommunity && !DATA.currentCommunity.is_default)return String(t?.name||'Tournament');
  const values=[t?.name,t?.sourceTournamentId,t?.id,t?.label];
  for(const value of values){
    const match=String(value||'').match(/(?:jak(?:arta)?[\s-]*sel(?:atan)?[\s-]*)?T\s*0*(\d+)\b/i);
    if(match)return `JakSel T${Number(match[1])}`;
  }
  const sequence=tournamentSequence(t||{});
  if(Number.isFinite(sequence)&&sequence!==Number.MAX_SAFE_INTEGER)return `JakSel T${sequence}`;
  if(Number.isInteger(index)&&index>=0)return `JakSel T${index+1}`;
  return String(t?.name||'Tournament');
}
function getTournaments(){const imported=loadImportedTournaments();const ids=new Set(imported.map(t=>t.id));return [...imported,...TOURNAMENTS.filter(t=>!ids.has(t.id))].sort((a,b)=>{const n=tournamentSequence(a)-tournamentSequence(b);if(n)return n;return String(a.dateISO||a.date||'').localeCompare(String(b.dateISO||b.date||''));});}
function getLatestTournament(){const verified=getTournaments().filter(t=>Array.isArray(t.podium)&&t.podium.length);return verified.length?verified[verified.length-1]:null;}
function saveImportedTournament(t){const current=loadImportedTournaments().filter(x=>x.id!==t.id);current.push(t);localStorage.setItem(ARCHIVE_KEY,JSON.stringify(current));}

